var longestBalanced = function(nums) {
    const n = nums.length;
    let res = 0;

    // 3 2 2 5 4
    // odd  - 1  1 1 2 2
    // even - 0  1 2 2 3
    // diff - -1 0 1 0 1

    const odd = new Array(n + 1).fill(0);
    const oddS = new Set();
    const even = new Array(n + 1).fill(0);
    const evenS = new Set();
    const diff = new Array(n + 1).fill(0);

    const seen = new Map();
    seen.set(0, 0);

    for (let i = 0; i < n; i++) {
        if (nums[i] & 1) {
            oddS.add(nums[i]);
            odd[i + 1] = oddS.size;
            even[i + 1] = even[i] || 0;
        } else {
            evenS.add(nums[i]);
            even[i + 1] = evenS.size;
            odd[i + 1] = odd[i] || 0;
        }

        diff[i + 1] = even[i + 1] - odd[i + 1];

        if (!seen.has(diff[i + 1])) {
            seen.set(diff[i + 1], i + 1);
        }
    }

    //console.log(odd, even, diff, seen);

    for (let i = n; i >= 0; i--) {
        if (seen.has(diff[i])) {
            res = Math.max(res, i - seen.get(diff[i]));
        }
    }

    return res;
};

class LazyTag {
    constructor() {
        this.toAdd = 0;
    }

    add(other) {
        this.toAdd += other.toAdd;
        return this;
    }

    hasTag() {
        return this.toAdd !== 0;
    }

    clear() {
        this.toAdd = 0;
    }
}

class SegmentTreeNode {
    constructor() {
        this.minValue = 0;
        this.maxValue = 0;
        // int data = 0; // only leaf nodes are used, this question does not require it.
        this.lazyTag = new LazyTag();
    }
}

class SegmentTree {
    constructor(data) {
        this.n = data.length;
        this.tree = new Array(this.n * 4 + 1)
            .fill(null)
            .map(() => new SegmentTreeNode());
        this.build(data, 1, this.n, 1);
    }

    add(l, r, val) {
        const tag = new LazyTag();
        tag.toAdd = val;
        this.update(l, r, tag, 1, this.n, 1);
    }

    findLast(start, val) {
        if (start > this.n) {
            return -1;
        }
        return this.find(start, this.n, val, 1, this.n, 1);
    }

    applyTag(i, tag) {
        this.tree[i].minValue += tag.toAdd;
        this.tree[i].maxValue += tag.toAdd;
        this.tree[i].lazyTag.add(tag);
    }

    pushdown(i) {
        if (this.tree[i].lazyTag.hasTag()) {
            const tag = new LazyTag();
            tag.toAdd = this.tree[i].lazyTag.toAdd;
            this.applyTag(i << 1, tag);
            this.applyTag((i << 1) | 1, tag);
            this.tree[i].lazyTag.clear();
        }
    }

    pushup(i) {
        this.tree[i].minValue = Math.min(
            this.tree[i << 1].minValue,
            this.tree[(i << 1) | 1].minValue,
        );
        this.tree[i].maxValue = Math.max(
            this.tree[i << 1].maxValue,
            this.tree[(i << 1) | 1].maxValue,
        );
    }

    build(data, l, r, i) {
        if (l == r) {
            this.tree[i].minValue = this.tree[i].maxValue = data[l - 1];
            return;
        }

        const mid = l + ((r - l) >> 1);
        this.build(data, l, mid, i << 1);
        this.build(data, mid + 1, r, (i << 1) | 1);

        this.pushup(i);
    }

    update(targetL, targetR, tag, l, r, i) {
        if (targetL <= l && r <= targetR) {
            this.applyTag(i, tag);
            return;
        }

        this.pushdown(i);
        const mid = l + ((r - l) >> 1);
        if (targetL <= mid) this.update(targetL, targetR, tag, l, mid, i << 1);
        if (targetR > mid)
            this.update(targetL, targetR, tag, mid + 1, r, (i << 1) | 1);
        this.pushup(i);
    }

    find(targetL, targetR, val, l, r, i) {
        if (this.tree[i].minValue > val || this.tree[i].maxValue < val) {
            return -1;
        }

        // according to the Intermediate Value Theorem, there must be a solution within this interval.
        if (l == r) {
            return l;
        }

        this.pushdown(i);
        const mid = l + ((r - l) >> 1);
        // targetL is definitely less than or equal to r (=n)
        if (targetR >= mid + 1) {
            const res = this.find(
                targetL,
                targetR,
                val,
                mid + 1,
                r,
                (i << 1) | 1,
            );
            if (res != -1) return res;
        }

        if (l <= targetR && mid >= targetL) {
            return this.find(targetL, targetR, val, l, mid, i << 1);
        }

        return -1;
    }
}

var longestBalanced = function (nums) {
    const occurrences = new Map();
    const sgn = (x) => (x % 2 == 0 ? 1 : -1);

    let len = 0;
    const prefixSum = new Array(nums.length).fill(0);

    prefixSum[0] = sgn(nums[0]);
    if (!occurrences.has(nums[0])) occurrences.set(nums[0], new Queue());
    occurrences.get(nums[0]).push(1);

    for (let i = 1; i < nums.length; i++) {
        prefixSum[i] = prefixSum[i - 1];
        if (!occurrences.has(nums[i])) occurrences.set(nums[i], new Queue());
        const occ = occurrences.get(nums[i]);
        if (occ.size() === 0) {
            prefixSum[i] += sgn(nums[i]);
        }
        occ.push(i + 1);
    }

    const seg = new SegmentTree(prefixSum);

    for (let i = 0; i < nums.length; i++) {
        len = Math.max(len, seg.findLast(i + len, 0) - i);

        let nextPos = nums.length + 1;
        const occ = occurrences.get(nums[i]);
        occ.pop();
        if (occ.size() > 0) {
            nextPos = occ.front();
        }

        seg.add(i + 1, nextPos - 1, -sgn(nums[i]));
    }

    return len;
};

class SegmentTree {
  constructor(n) {
    this.n = n
    this.minTree = new Array(4 * n).fill(0)
    this.maxTree = new Array(4 * n).fill(0)
    this.lazy = new Array(4 * n).fill(0)
  }

  push(node, start, end) {
    if (this.lazy[node] !== 0) {
      this.minTree[node] += this.lazy[node]
      this.maxTree[node] += this.lazy[node]
      if (start !== end) {
        this.lazy[node * 2] += this.lazy[node]
        this.lazy[node * 2 + 1] += this.lazy[node]
      }
      this.lazy[node] = 0
    }
  }

  updateRange(node, start, end, l, r, val) {
    this.push(node, start, end)
    if (start > end || start > r || end < l) return

    if (l <= start && end <= r) {
      this.lazy[node] += val
      this.push(node, start, end)
      return
    }

    const mid = Math.floor((start + end) / 2)
    this.updateRange(node * 2, start, mid, l, r, val)
    this.updateRange(node * 2 + 1, mid + 1, end, l, r, val)

    this.minTree[node] = Math.min(
      this.minTree[node * 2],
      this.minTree[node * 2 + 1]
    )
    this.maxTree[node] = Math.max(
      this.maxTree[node * 2],
      this.maxTree[node * 2 + 1]
    )
  }

  findLeftmostZero(node, start, end) {
    this.push(node, start, end)
    if (this.minTree[node] > 0 || this.maxTree[node] < 0) return -1
    if (start === end) return this.minTree[node] === 0 ? start : -1

    const mid = Math.floor((start + end) / 2)
    const left = this.findLeftmostZero(node * 2, start, mid)
    if (left !== -1) return left
    return this.findLeftmostZero(node * 2 + 1, mid + 1, end)
  }
}

function longestBalanced(nums) {
  const n = nums.length
  const prev = new Map()
  const st = new SegmentTree(n)
  let res = 0

  for (let r = 0; r < n; r++) {
    const v = nums[r]
    const val = v % 2 === 0 ? 1 : -1

    if (prev.has(v)) {
      st.updateRange(1, 0, n - 1, 0, prev.get(v), -val)
    }

    st.updateRange(1, 0, n - 1, 0, r, val)
    prev.set(v, r)

    const l = st.findLeftmostZero(1, 0, n - 1)
    if (l !== -1 && l <= r) res = Math.max(res, r - l + 1)
  }

  return res
}
